local function murloc(ctx,e)for _,tag in ipairs(ctx:card_definition(ctx:entity(e).card_id).tags)do if tag=="murloc"or tag=="all"then return true end end return false end
return {api_version=1,id="EX1_508",name="Grimscale Oracle",text="Your other Murlocs have +1 Attack.",set="LEGACY",type="minion",cost=1,attack=1,health=1,tags={"murloc"},auras={{active_zones={"board"},attack=1,targets=function(ctx,self)local r={};for _,e in ipairs(ctx:friendly_minions(self))do if e~=self and murloc(ctx,e)then r[#r+1]=e end end;return r end}}}
